u_char *
MakeQuantHeader(u_char *p, u_char *qt, int tableNo)
{
        *p++ = 0xff;
        *p++ = 0xdb;            /* DQT */
        *p++ = 0;               /* 長さの上位バイト */
        *p++ = 67;              /* 長さの下位バイト */
        *p++ = tableNo;
        memcpy(p, qt, 64);
        return (p + 64);
}

u_char *
MakeHuffmanHeader(u_char *p, u_char *codelens, int ncodes,
                  u_char *symbols, int nsymbols, int tableNo,
                  int tableClass)
{
        *p++ = 0xff;

        *p++ = 0xc4;            /* DHT */
        *p++ = 0;               /* 長さの上位バイト */
        *p++ = 3 + ncodes + nsymbols; /* 長さの下位バイト */
        *p++ = (tableClass << 4) | tableNo;
        memcpy(p, codelens, ncodes);
        p += ncodes;
        memcpy(p, symbols, nsymbols);
        p += nsymbols;
        return (p);
}

u_char *
MakeDRIHeader(u_char *p, u_short dri) {
        *p++ = 0xff;
        *p++ = 0xdd;            /* DRI */
        *p++ = 0x0;             /* 長さの上位バイト */
        *p++ = 4;               /* 長さの下位バイト */
        *p++ = dri >> 8;        /* driの上位バイト */
        *p++ = dri & 0xff;      /* driの下位バイト */
        return (p);
}

/*
 *  引数:
 *    type, width, height: RTP/JPEGヘッダーで与えられたもの
 *    lqt, cqt: MakeTables()を使用してQフィールドから
 *         導出された、または4.2節で規定されて
 *         いる量子化テーブル。
 *    dri: MCU単位の再開間隔、再開がない場合は0。
 *
 *    p: 結果を返す領域へのポインター
 *
 *  戻り値:
 *    生成されたヘッダーの長さ。
 *
 *    RTP/JPEGのデータペイロードの前に付加して、交換形式の
 *    JPEG圧縮画像（末尾にゴミが残る可能性と、スキャンを終端
 *    するEOIマーカーがないことを除く）を生成できる、フレーム
 *    ヘッダーとスキャンヘッダーを生成する。
 */
int MakeHeaders(u_char *p, int type, int w, int h, u_char *lqt,
                u_char *cqt, u_short dri)
{
        u_char *start = p;

        /* ブロックからピクセルに変換する */
        w <<= 3;
        h <<= 3;

        *p++ = 0xff;
        *p++ = 0xd8;            /* SOI */

        p = MakeQuantHeader(p, lqt, 0);
        p = MakeQuantHeader(p, cqt, 1);

        if (dri != 0)
                p = MakeDRIHeader(p, dri);

        *p++ = 0xff;
        *p++ = 0xc0;            /* SOF */
        *p++ = 0;               /* 長さの上位バイト */
        *p++ = 17;              /* 長さの下位バイト */
        *p++ = 8;               /* 8ビット精度 */
        *p++ = h >> 8;          /* 高さの上位バイト */
        *p++ = h;               /* 高さの下位バイト */
        *p++ = w >> 8;          /* 幅の上位バイト */
        *p++ = w;               /* 幅の下位バイト */
        *p++ = 3;               /* コンポーネントの数 */
        *p++ = 0;               /* コンポーネント0 */
        if (type == 0)
                *p++ = 0x21;    /* hsamp = 2, vsamp = 1 */
        else
                *p++ = 0x22;    /* hsamp = 2, vsamp = 2 */
        *p++ = 0;               /* 量子化テーブル0 */
        *p++ = 1;               /* コンポーネント1 */
        *p++ = 0x11;            /* hsamp = 1, vsamp = 1 */
        *p++ = 1;               /* 量子化テーブル1 */
        *p++ = 2;               /* コンポーネント2 */
        *p++ = 0x11;            /* hsamp = 1, vsamp = 1 */
        *p++ = 1;               /* 量子化テーブル1 */
        p = MakeHuffmanHeader(p, lum_dc_codelens,
                              sizeof(lum_dc_codelens),
                              lum_dc_symbols,
                              sizeof(lum_dc_symbols), 0, 0);
        p = MakeHuffmanHeader(p, lum_ac_codelens,
                              sizeof(lum_ac_codelens),
                              lum_ac_symbols,
                              sizeof(lum_ac_symbols), 0, 1);
        p = MakeHuffmanHeader(p, chm_dc_codelens,
                              sizeof(chm_dc_codelens),
                              chm_dc_symbols,
                              sizeof(chm_dc_symbols), 1, 0);
        p = MakeHuffmanHeader(p, chm_ac_codelens,
                              sizeof(chm_ac_codelens),
                              chm_ac_symbols,
                              sizeof(chm_ac_symbols), 1, 1);

        *p++ = 0xff;
        *p++ = 0xda;            /* SOS */
        *p++ = 0;               /* 長さの上位バイト */
        *p++ = 12;              /* 長さの下位バイト */
        *p++ = 3;               /* 3コンポーネント */
        *p++ = 0;               /* コンポーネント0 */
        *p++ = 0;               /* ハフマンテーブル0 */
        *p++ = 1;               /* コンポーネント1 */
        *p++ = 0x11;            /* ハフマンテーブル1 */
        *p++ = 2;               /* コンポーネント2 */
        *p++ = 0x11;            /* ハフマンテーブル1 */
        *p++ = 0;               /* 最初のDCT係数 */
        *p++ = 63;              /* 最後のDCT係数 */
        *p++ = 0;               /* 逐次近似 */

        return (p - start);
};

/*
 * RFC1889のRTPデータヘッダー
 */
typedef struct {
        unsigned int version:2;   /* プロトコルのバージョン */
        unsigned int p:1;         /* パディングのフラグ */
        unsigned int x:1;         /* ヘッダー拡張のフラグ */
        unsigned int cc:4;        /* CSRCの数 */
        unsigned int m:1;         /* マーカービット */
        unsigned int pt:7;        /* ペイロードタイプ */
        u_int16 seq;              /* シーケンス番号 */
        u_int32 ts;               /* タイムスタンプ */
        u_int32 ssrc;             /* 同期送信元 */
        u_int32 csrc[1];          /* 選択可能なCSRCのリスト */
} rtp_hdr_t;

#define RTP_HDR_SZ 12

/* 次の定義はRFC1890からのもの */
#define RTP_PT_JPEG             26

struct jpeghdr {
        unsigned int tspec:8;   /* タイプ固有のフィールド */
        unsigned int off:24;    /* フラグメントのバイトオフセット */
        u_int8 type;            /* JPEG復号器のパラメーターのID */
        u_int8 q;               /* 量子化係数（またはテーブルID） */
        u_int8 width;           /* 8ピクセルのブロック単位のフレームの幅 */
        u_int8 height;          /* 8ピクセルのブロック単位のフレームの高さ */
};

struct jpeghdr_rst {
        u_int16 dri;
        unsigned int f:1;
        unsigned int l:1;
        unsigned int count:14;
};

struct jpeghdr_qtable {
        u_int8  mbz;
        u_int8  precision;
        u_int16 length;
};

#define RTP_JPEG_RESTART           0x40

/* 手続きSendFrame:
 *
 *  引数:
 *    start_seq: 現在のフレームの最初のパケットのシーケンス
 *               番号。
 *    ts: 現在のフレームのRTPタイムスタンプ
 *    ssrc: RTPのSSRCの値
 *    jpeg_data: ハフマン符号化されたJPEGのスキャンデータ
 *    len: JPEGのスキャンデータの長さ
 *    type: RTP/JPEGのtypeフィールドに設定すべき値
 *    typespec: RTP/JPEGのtype-specificフィールドに設定すべき
 *              値
 *    width: JPEG画像のピクセル単位の幅
 *    height: JPEG画像のピクセル単位の高さ
 *    dri: 再開マーカーの間のMCUの数（データに再開マーカーが
 *         ない場合は0）
 *    q: データのQ係数。1 <= q <= 99の場合はIndependent JPEG
 *       Groupのアルゴリズムを使用して指定され、q >= 128の場合は
 *       lqtとcqtで明示的に指定され、それ以外の場合は未定義。
 *    lqt: q >= 128の場合の輝度チャネルの量子化テーブル
 *    cqt: q >= 128の場合のクロミナンスチャネルの
 *         量子化テーブル
 *
 *  戻り値:
 *    次のフレームの最初のパケットで送信されるシーケンス
 *    番号。
 *
 * 次のものが定義されていると仮定する:
 *
 * PACKET_SIZE                         - 送信するパケットのサイズ
 * send_packet(u_int8 *data, int len)  - パケットをネットワークに送信する
 */

u_int16 SendFrame(u_int16 start_seq, u_int32 ts, u_int32 ssrc,
                   u_int8 *jpeg_data, int len, u_int8 type,
                   u_int8 typespec, int width, int height, int dri,
                   u_int8 q, u_int8 *lqt, u_int8 *cqt) {
        rtp_hdr_t rtphdr;
        struct jpeghdr jpghdr;
        struct jpeghdr_rst rsthdr;
        struct jpeghdr_qtable qtblhdr;
        u_int8 packet_buf[PACKET_SIZE];
        u_int8 *ptr;
        int bytes_left = len;
        int seq = start_seq;
        int pkt_len, data_len;

        /* RTPヘッダーを初期化する
         */
        rtphdr.version = 2;
        rtphdr.p = 0;
        rtphdr.x = 0;
        rtphdr.cc = 0;
        rtphdr.m = 0;
        rtphdr.pt = RTP_PT_JPEG;
        rtphdr.seq = start_seq;
        rtphdr.ts = ts;
        rtphdr.ssrc = ssrc;

        /* JPEGヘッダーを初期化する
         */
        jpghdr.tspec = typespec;
        jpghdr.off = 0;
        jpghdr.type = type | ((dri != 0) ? RTP_JPEG_RESTART : 0);
        jpghdr.q = q;
        jpghdr.width = width / 8;
        jpghdr.height = height / 8;

        /* DRIヘッダーを初期化する
         */
        if (dri != 0) {
                rsthdr.dri = dri;
                rsthdr.f = 1;        /* このコードはRIを揃えない */
                rsthdr.l = 1;
                rsthdr.count = 0x3fff;
        }

        /* 量子化テーブルヘッダーを初期化する
         */
        if (q >= 128) {
                qtblhdr.mbz = 0;
                qtblhdr.precision = 0; /* このコードは8ビットのテーブルだけを使用する */
                qtblhdr.length = 128;  /* 64バイトのテーブルが2つ */
        }

        while (bytes_left > 0) {
                ptr = packet_buf + RTP_HDR_SZ;
                memcpy(ptr, &jpghdr, sizeof(jpghdr));
                ptr += sizeof(jpghdr);

                if (dri != 0) {
                        memcpy(ptr, &rsthdr, sizeof(rsthdr));
                        ptr += sizeof(rsthdr);
                }

                if (q >= 128 && jpghdr.off == 0) {
                        memcpy(ptr, &qtblhdr, sizeof(qtblhdr));
                        ptr += sizeof(qtblhdr);
                        memcpy(ptr, lqt, 64);
                        ptr += 64;
                        memcpy(ptr, cqt, 64);
                        ptr += 64;
                }

                data_len = PACKET_SIZE - (ptr - packet_buf);
                if (data_len >= bytes_left) {
                        data_len = bytes_left;
                        rtphdr.m = 1;
                }

                memcpy(packet_buf, &rtphdr, RTP_HDR_SZ);
                memcpy(ptr, jpeg_data + jpghdr.off, data_len);

                send_packet(packet_buf, (ptr - packet_buf) + data_len);

                jpghdr.off += data_len;
                bytes_left -= data_len;
                rtphdr.seq++;
        }
        return rtphdr.seq;
}
